import { ImageVariations } from '../../../models/image.model'
import { mergeAttributes } from '@tiptap/core'
import Image from '@tiptap/extension-image'

type Options = {
  src: string
  alt?: string
  title?: string
  width?: number
  height?: number
  size?: ImageVariations
}

declare module '@tiptap/core' {
  interface Commands<ReturnType> {
    CustomImage: {
      setImage: (options: Options) => ReturnType
    }
  }
}

export default Image.extend({
  name: 'image',

  addAttributes() {
    return {
      ...(Image?.config?.addAttributes?.call(this) || {}),
      size: {
        default: null,
        rendered: false,
      },
    }
  },

  addOptions() {
    return {
      ...Image.options,
      inline: true,
      HTMLAttributes: {},
      sizes: ['small', 'medium', 'large', 'full', 'custom', 'original'] as ImageVariations[],
      allowBase64: false,
    }
  },

  inline() {
    return this.options.inline
  },

  group() {
    return this.options.inline ? 'inline' : 'block'
  },

  draggable: true,

  addCommands() {
    return {
      // This is unchanged from the original
      // Image setImage function
      // However, if I extended addComands in
      // the same way as addAttributes `this`
      // seemed to lose context, so I've just
      // copied it in here directly
      setImage:
        (options: Options) =>
        ({ tr, dispatch }) => {
          if (!options['size']) {
            options = {
              ...options,
              size: 'original',
            } as any // TODO: fix ts type
          }
          const { selection } = tr
          const node = this.type.create(options)

          if (dispatch) {
            tr.replaceRangeWith(selection.from, selection.to, node)
          }

          return true
        },
    }
  },

  renderHTML({ node, HTMLAttributes }) {
    // When we render the HTML, grab the
    // size and add an appropriate
    // corresponding class

    const size = node.attrs.size
    HTMLAttributes.class = ' custom-image-' + size

    return ['img', mergeAttributes(this.options.HTMLAttributes, HTMLAttributes)]
  },

  parseHTML() {
    const getAttrs = (dom: HTMLElement) => {
      let size: ImageVariations = 'original'
      const sizes = (this.options as any).sizes as ImageVariations[]

      sizes.forEach((s) => {
        const hasSize = dom.classList.contains('custom-image-' + s)
        if (hasSize) {
          size = s
        }
      })
      return {
        src: dom.getAttribute('src'),
        title: dom.getAttribute('title'),
        alt: dom.getAttribute('alt'),
        size: size,
      }
    }
    return [
      {
        tag: 'img[src]',
        getAttrs,
      },
    ]
  },
})
